import { useState } from 'react';

export type Signal = 'stop' | 'ready' | 'go';
export type Props = { onChange: (signal: Signal) => void };

const theme = {
  colors: { panel: '#eef4ff', text: '#17345c' },
  spacing: { padding: 12, gap: 6 },
};

const nextSignals = {
  stop: 'ready',
  ready: 'go',
  go: 'stop',
} as const;

export function Component({ onChange }: Props) {
  const [signal, setSignal] = useState<Signal>('stop');

  return (
    <div
      data-testid="panel"
      style={{
        display: 'grid',
        background: theme.colors.panel,
        color: theme.colors.text,
        padding: theme.spacing.padding,
        gap: theme.spacing.gap,
      }}
    >
      <output aria-label="Signal">{signal}</output>
      <button
        type="button"
        onClick={() => {
          const next = nextSignals[signal];
          setSignal(next);
          onChange(next);
        }}
      >
        Next
      </button>
      <button
        type="button"
        disabled={signal === 'stop'}
        onClick={() => {
          if (signal === 'stop') return;
          setSignal('stop');
          onChange('stop');
        }}
      >
        Reset
      </button>
    </div>
  );
}
